import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const UserDashboard = () => {
  const [slots, setSlots] = useState([]);
  const [filter, setFilter] = useState("all");
  const [query, setQuery] = useState("");

  useEffect(() => {
    fetchSlots();
    const intv = setInterval(fetchSlots, 3000);
    return () => clearInterval(intv);
  }, []);

  async function fetchSlots() {
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("slot", { ascending: true });
    if (error) console.log("Error fetching slots:", error);
    else setSlots(data || []);
  }

  const filtered = slots.filter((s) => {
    if (filter === "occupied" && s.status !== "occupied") return false;
    if (filter === "vacant" && s.status !== "vacant") return false;
    if (query && !String(s.slot).includes(query) && !(s.plate || "").toLowerCase().includes(query.toLowerCase())) return false;
    return true;
  });

  const total = slots.length;
  const occupied = slots.filter(s => s.status === "occupied").length;
  const vacant = total - occupied;

  return (
    <main className="dashboard-root">
      <section className="summary-row">
        <div className="summary-card blue">
          <div className="summary-title">Total Slots</div>
          <div className="summary-num">{total}</div>
        </div>

        <div className="summary-card green">
          <div className="summary-title">Available Slots</div>
          <div className="summary-num">{vacant}</div>
        </div>

        <div className="summary-card red">
          <div className="summary-title">Occupied Slots</div>
          <div className="summary-num">{occupied}</div>
        </div>

        <div className="controls">
          <input className="search" placeholder="Search slot or plate..." value={query} onChange={e => setQuery(e.target.value)} />
          <select className="filter" value={filter} onChange={e => setFilter(e.target.value)}>
            <option value="all">All</option>
            <option value="occupied">Occupied</option>
            <option value="vacant">Vacant</option>
          </select>
        </div>
      </section>

      <section className="layout-title">Parking Slots</section>

      <section className="slots-grid">
        {filtered.map(slot => <SlotCard key={slot.id} slot={slot} />)}
      </section>

      <footer className="small-footer">Updated: {new Date().toLocaleString()}</footer>
    </main>
  );
};

export default UserDashboard;
